func TestABitmapKnowsItsShape(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(5, 3, 3)
	port.AssertEq(emonT, port.BitmapW(b), 5, "width")
	port.AssertEq(emonT, port.BitmapH(b), 3, "height")
	port.AssertEq(emonT, port.BitmapChannels(b), 3, "channels")
	port.AssertEq(emonT, port.BitmapStride(b), 15, "stride is width times channels")
	port.AssertEq(emonT, port.BitmapU8(b, 4, 2, 2), 0, "a new bitmap is zero")
}

func TestAWrittenByteReadsBackAndTouchesNothingElse(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(4, 2, 3)
	port.BitmapSetU8(b, 3, 1, 2, 200)
	port.BitmapSetU8(b, 0, 0, 0, 7)
	port.AssertEq(emonT, port.BitmapU8(b, 3, 1, 2), 200, "the byte written")
	port.AssertEq(emonT, port.BitmapU8(b, 3, 1, 1), 0, "its neighbour channel")
	port.AssertEq(emonT, port.BitmapU8(b, 2, 1, 2), 0, "its neighbour pixel")
	port.AssertEq(emonT, port.BitmapU8(b, 0, 0, 0), 7, "the other write")
}

